	/**
	 * Write data for plugin; writes the current selection.
	 */
	/* @Override */
	public void writeDataState(SaveState saveState) {
		componentProvider.writeDataState(saveState);

		saveState.putInt(NUMBER_OF_VIEWS, providerMap.size());
		int idx = 0;
		foreach (string treeName in providerMap.keySet()) {
			saveState.putString(TREE_NAME + "-" + idx, treeName);
			TreeViewProvider provider = providerMap.get(treeName);
			provider.writeDataState(saveState);
			++idx;
		}
		saveState.putBoolean(TOGGLE_STATE, selectionToggleAction.isSelected());
	}

	/**
	 * Read the data for the plugin upon deserialization; reads what should be the current selection
	 * in the tree.
	 */
	/* @Override */
	public void readDataState(SaveState saveState) {

		int numberOfViews = saveState.getInt(NUMBER_OF_VIEWS, 0);

		List<TreeViewProvider> viewList = new();

		string[] treeNames = new string[numberOfViews];
		for (int i = 0; i < numberOfViews; i++) {
			treeNames[i] = saveState.getString(TREE_NAME + "-" + i, null);
		}

		List<TreeViewProvider> providerList = new();
		foreach (string element in treeNames) {
			TreeViewProvider provider = providerMap.get(element);
			if (provider != null) {
				providerList.add(provider);
			}
		}

		foreach (string treeName in treeNames) {
			TreeViewProvider provider = providerMap.get(treeName);
			if (!treeExists(treeName)) {
				if (provider != null) {
					deregisterService(typeof(TreeViewProvider), provider);
					providerMap.remove(treeName);
					provider = null;
				}
			}
			else if (provider == null) {
				provider = addTreeView(treeName);
			}
			if (provider != null) {
				reloadTree(provider.getProgramDnDTree(), true);
				provider.readDataState(saveState);
				viewList.add(provider);
			}
		}
		removeStaleProviders(viewList);

		// If nothing is showing, then display the first program tree found.
		if (viewList.isEmpty()) {
			addTreeViews();
		}

		selectionToggleAction.setSelected(saveState.getBoolean(TOGGLE_STATE, true));

		restoreTreeViews();

		componentProvider.readDataState(saveState);
	}

	private void restoreTreeViews() {
		if (currentProgram == null) {
			return;
		}

		//
		// Update low-level component cache.  We want to maintain the order of the tree views so 
		// that the UI does not move around on the user.  Use the view names as they are stored in 
		// the program to provide a consistent order. Do not open trees the user has closed.
		//		
		List<TreeViewProvider> list = new();
		string[] orderedTreeNames = currentProgram.getListing().getTreeNames();
		foreach (string treeName in orderedTreeNames) {
			TreeViewProvider provider = providerMap.get(treeName);
			if (provider != null) { // Provider will be null if this tree is not open in the view
				list.add(provider);
			}
		}

		componentProvider.treeViewsRestored(list);
	}

