	private void removeStaleProviders(List<TreeViewProvider> providerList) {
		Map<string, TreeViewProvider> map = new(providerMap);
		foreach (string treeName in map.keySet()) {
			TreeViewProvider provider = map.get(treeName);
			if (!providerList.contains(provider)) {
				deregisterService(typeof(ViewProviderService), provider);
				providerMap.remove(treeName);
			}
		}
	}

